TypeScript idempotency key example:
```ts
import * as crypto from 'crypto'
function idempotencyKeyV2(customerNs: string, route: string, payload: Buffer) {
  const shortHash = crypto.createHash('sha256').update(payload).digest('hex').slice(0,48)
  const window = Math.floor(Date.now() / 60000).toString()
  const msg = `${customerNs}|${route}|${shortHash}|${window}`
  const hmac = crypto.createHmac('sha256', process.env.IDEMP_SECRET!)
  hmac.update(msg)
  return hmac.digest('base64url')
}
```
